import java.util.PriorityQueue;
import java.util.Objects;

public class MutableJobQueue {
    public static class Job implements Comparable<Job> {
        final String id;
        int priority;

        public Job(String id, int priority) {
            this.id = id;
            this.priority = priority;
        }

        @Override
        public int compareTo(Job o) {
            return Integer.compare(this.priority, o.priority);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Job)) return false;
            Job job = (Job) o;
            return Objects.equals(id, job.id);
        }

        @Override
        public int hashCode() {
            return Objects.hash(id);
        }
    }

    private final PriorityQueue<Job> pq = new PriorityQueue<>();

    public void add(Job job) {
        pq.offer(job);
    }

    public void updatePriority(Job job, int newPriority) {
        boolean removed = pq.remove(job);
        job.priority = newPriority;
        if (removed) {
            pq.offer(job);
        }
    }

    public Job poll() {
        return pq.poll();
    }

    public static void main(String[] args) {
        MutableJobQueue queue = new MutableJobQueue();
        Job j1 = new Job("J1", 10);
        Job j2 = new Job("J2", 20);
        queue.add(j1);
        queue.add(j2);

        queue.updatePriority(j2, 5);
        System.out.println(queue.poll().id);
        System.out.println(queue.poll().id);
    }
}

