import java.util.ArrayDeque;
import java.util.Queue;
import java.util.HashMap;
import java.util.Map;

public class StreamFirstUnique {
    private final Queue<Character> queue = new ArrayDeque<>();
    private final Map<Character, Integer> counts = new HashMap<>();

    public void add(char c) {
        counts.put(c, counts.getOrDefault(c, 0) + 1);
        queue.offer(c);
    }

    public char getFirstUnique() {
        while (!queue.isEmpty() && counts.get(queue.peek()) > 1) {
            queue.poll();
        }
        return queue.isEmpty() ? '#' : queue.peek();
    }

    public static void main(String[] args) {
        StreamFirstUnique stream = new StreamFirstUnique();
        stream.add('a');
        System.out.println(stream.getFirstUnique());
        stream.add('b');
        System.out.println(stream.getFirstUnique());
        stream.add('a');
        System.out.println(stream.getFirstUnique());
        stream.add('b');
        System.out.println(stream.getFirstUnique());
    }
}
